Q: Java-like executor service for javascript using WebWorkers A: <p><strong>Usage</strong></p>
<pre><code>&lt;script type=&quot;module&quot;&gt;
  import { Executor } from &quot;./Executor.js&quot;
  const executor = new Executor(3, (e) =&gt; {
    console.log(`Progress : ${JSON.stringify(e)}`)
  })

  const futures = []
  for (let i = 1; i &lt;= 10; i++) {
    futures.push({
      id: i,
      promise: executor.submit(sumTo, [i * 100_000_000])
    })
  }

  for (const future of futures) {
    const result = await future.promise
    console.log(`Task ${future.id}: ${result}`)
  }

  executor.close()

  function sumTo(n) {
    let sum = 0
    for (let i = 1; i &lt;= n; i++) {
      sum += i
    }
    return sum
    // throw new Error(&quot;blah&quot;)
  }
&lt;/script&gt;
</code></pre>
<p><strong>Executor.js</strong></p>
<pre><code>export class Executor {

  constructor(workerCount, onProgress = () =&gt; { }) {
    this.workerCount = workerCount
    this.onProgress = onProgress

    this.workers = []
    this.queue = []
    this.running = new Map()

    this.taskCounter = 0
    this.closed = false
  }

  /**
   * @template T
   * @param {(...args:any[]) =&gt; T | Promise&lt;T&gt;} run
   * @param {Array&lt;any&gt;} args
   * @returns {Promise&lt;T&gt;}
   */
  submit(run, args = []) {
    if (this.closed) return Promise.reject(new Error(&quot;Executor is closed&quot;))
    return new Promise((resolve, reject) =&gt; {
      const task = { id: ++this.taskCounter, run, args, resolve, reject }
      this.queue.push(task)
      this.runWorker()
    })
  }

  runWorker() {
    while (this.workers.length &lt; this.workerCount) {
      this.workers.push(this.createWorker())
    }

    for (const worker of this.workers) {
      if (this.queue.length === 0) return
      if (worker.busy) continue

      const task = this.queue.shift()
      this.running.set(task.id, { task, worker })

      worker.busy = true
      worker.postMessage({
        id: task.id,
        run: task.run.toString(),
        args: task.args
      })
    }
  }

  createWorker() {
    const source = `(${workerTemplate.toString()})();`
    const url = URL.createObjectURL(new Blob([source], { type: &quot;application/javascript&quot; }))
    const worker = new Worker(url)
    URL.revokeObjectURL(url)

    worker.busy = false
    worker.onmessage = e =&gt; {
      worker.busy = false
      const { id, result, error } = e.data
      const running = this.running.get(id)
      if (!running) return

      this.running.delete(id)
      if (error) {
        running.task.reject(error)
      } else {
        running.task.resolve(result)
      }

      this.onProgress({ completed: id, queued: this.queue.length, running: this.running.size })
      this.runWorker()
    }

    worker.onerror = e =&gt; {
      worker.busy = false
      for (const [id, running] of this.running) {
        if (running.worker === worker) {
          this.running.delete(id)
          running.task.reject(e instanceof Error ? e : new Error(String(e)))
          break
        }
      }
      this.runWorker()
    }

    return worker
  }

  close() {
    this.closed = true
    for (const task of this.queue)
      task.reject(new Error(&quot;Executor is closed&quot;))

    for (const { task } of this.running.values())
      task.reject(new Error(&quot;Executor is closed&quot;))

    for (const worker of this.workers)
      worker.terminate()

    this.workers = []
    this.queue = []
    this.running.clear()
  }
}

function workerTemplate() {
  self.onmessage = async e =&gt; {
    const { id, run, args } = e.data
    try {
      const fn = eval(`
        (${run})
        //# sourceURL=executor-task-${id}.js`)
      const result = await fn(...args)
      self.postMessage({ id, result })
    } catch (e) {
      const err = e instanceof Error ? e : new Error(String(e))
      self.postMessage({ id, error: err })
    }
  }
}
</code></pre>

Q: How to return boolean value from custom function in react A: <p>This is because docRef.get returns promise and you are treating it as a normal function call. Try using this :</p>
<pre><code>const App = async ({ user, database }) =&gt; {
  const PaidMembership = async () =&gt; {
    const doc = await docRef.get();
    return doc.exists;
  };

  return (await PaidMembership()) ? &quot;render&quot; : &quot;dont render&quot;;
};
</code></pre>
